n = len(s)
codon = {}
aas = "FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
bs = "TCAG"; k = 0
for b1 in bs:
    for b2 in bs:
        for b3 in bs:
            codon[b1+b2+b3] = aas[k]; k += 1

STOP = set("TAA TAG TGA".split())
def translate(frame_strand, start_nt):
    prot = []
    i = start_nt
    while i+2 < len(frame_strand):
        c = frame_strand[i:i+3]
        if c in STOP: break
        prot.append(codon[c]); i += 3
    return "".join(prot) + ("*" if i+2 < len(frame_strand) else "")

# Forward strand frames: index 0,1,2
frames = s, s[1:], s[2:]
for fi, fr in enumerate(frames):
    orfs = []
    for i in range(len(fr)):
        if fr[i:i+3] == "ATG":
            aa = translate(fr, i)
            if aa.count("*") == 1 and len(aa) >= 40:
                orfs.append((i+1+fi, len(aa), aa))
    if orfs:
        best = max(orfs, key=lambda t: t[1])
        print("Forward frame +%d: %d ORFs; longest: start=%d len=%d aa" % (fi+1, len(orfs), best[0], best[1]))
        print("  ", best[2][:70])
